npx supabase db query "UPDATE leads SET status = 'NEW';"
npx supabase db query "ALTER TABLE leads ADD CONSTRAINT leads_status_check CHECK (status = ANY (ARRAY['NEW', 'UNREAD', 'ASSIGNED', 'CONTACT_ATTEMPTED', 'CONTACTED', 'QUALIFIED', 'CONSULTATION_SCHEDULED', 'CONSULTATION_COMPLETED', 'CONVERTED', 'ON_HOLD', 'LOST', 'BLACKLISTED']));"
npx supabase db query "ALTER TABLE leads ALTER COLUMN status SET DEFAULT 'NEW';"
npx supabase db query "ALTER TABLE leads ADD COLUMN IF NOT EXISTS next_followup_date TIMESTAMP WITH TIME ZONE;"
npx supabase db query "ALTER TABLE leads ADD COLUMN IF NOT EXISTS followup_notes TEXT;"
npx supabase db query "ALTER TABLE leads ADD COLUMN IF NOT EXISTS priority TEXT DEFAULT 'MEDIUM' CHECK (priority IN ('HIGH', 'MEDIUM', 'LOW'));"
npx supabase db query "CREATE TABLE IF NOT EXISTS lead_documents ( id UUID DEFAULT gen_random_uuid() PRIMARY KEY, lead_id UUID NOT NULL REFERENCES leads(id) ON DELETE CASCADE, file_url TEXT NOT NULL, file_name TEXT NOT NULL, uploaded_by UUID REFERENCES profiles(id), uploaded_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );"
